@keyframes pulse {
  0%,
  100% {
    opacity: 1;
  }
  50% {
    opacity: 0.5;
  }
}

/* ── View Transition: directional page slides ── */

@keyframes vt-slide-out-forward {
  to {
    transform: translateX(-40px);
    opacity: 0;
  }
}

@keyframes vt-slide-in-forward {
  from {
    transform: translateX(40px);
    opacity: 0;
  }
}

@keyframes vt-slide-out-back {
  to {
    transform: translateX(40px);
    opacity: 0;
  }
}

@keyframes vt-slide-in-back {
  from {
    transform: translateX(-40px);
    opacity: 0;
  }
}

:root[data-nav-dir="forward"]::view-transition-old(root) {
  animation: vt-slide-out-forward 0.35s cubic-bezier(0.4, 0, 0.2, 1) both;
}

:root[data-nav-dir="forward"]::view-transition-new(root) {
  animation: vt-slide-in-forward 0.35s cubic-bezier(0.4, 0, 0.2, 1) both;
}

:root[data-nav-dir="back"]::view-transition-old(root) {
  animation: vt-slide-out-back 0.35s cubic-bezier(0.4, 0, 0.2, 1) both;
}

:root[data-nav-dir="back"]::view-transition-new(root) {
  animation: vt-slide-in-back 0.35s cubic-bezier(0.4, 0, 0.2, 1) both;
}

/* ── Shared element: product image morph ── */

::view-transition-group(product-image-classic-sneakers),
::view-transition-group(product-image-leather-backpack),
::view-transition-group(product-image-wireless-headphones),
::view-transition-group(product-image-cotton-hoodie) {
  animation-duration: 0.5s;
  animation-timing-function: cubic-bezier(0.4, 0, 0.2, 1);
}

/* ── Reduced motion: disable all custom view-transition animations ── */

@media (prefers-reduced-motion: reduce) {
  ::view-transition-group(*),
  ::view-transition-old(*),
  ::view-transition-new(*) {
    animation-duration: 0s !important;
  }

  .product-info {
    animation: none !important;
  }
}

/* ── Content reveal for Suspense → content ── */

.product-info {
  animation: content-reveal 0.35s cubic-bezier(0.4, 0, 0.2, 1) both;
}

@keyframes content-reveal {
  from {
    opacity: 0;
    transform: translateY(6px);
  }
}

